  AwakerTalent_122607_TalentDesc_1 = {
    Text = "·เมื่อเล่นไพ่ใบที่ 2「ตี」 โมช่าจะทำการโจมตีไล่ล่า ทำให้เกิดความเสียหายแบบสุ่ม 1 ครั้งที่ 30% ของพลังโจมตีของโมช่า และนับเป็นความเสียหาย「ตี」 สูงสุดสามารถเกิดขึ้นได้ 4 ครั้งต่อรอบ."
  },
  AwakerTalent_122607_TalentName_1 = {
    Text = "การพบกันที่เต็มไปด้วยดราม่า"
  },
  AwakerTalent_125362_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「星辰篇」เท่านั้น.\n·CON, การโจมตี, การป้องกัน ของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] ％ และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] จุด หลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·ผลพิษที่ผู้ปลุกตื่นทุกคนปล่อยออกมาเพิ่มขึ้น [Arg3]％ .\n·「เมามาย」แต่ละชั้นจะลดความเสียหายที่ศัตรู「รูปร่างมนุษย์」สร้างเพิ่มเติม 1％, และเมื่อถูกลบออกจะสร้างความเสียหายบริสุทธิ์ต่อ Max HP 1％ แก่ศัตรู「รูปร่างมนุษย์」เพิ่มเติม."
  },
