  AwakerTalent_127223_TalentDesc_1 = {
    Text = "·เมื่อ อารัคเน อยู่ในทีม จะแทนที่ดินแดน「อัลตร้า」ด้วยดินแดน「เอกภาวะ: อัลตร้า」\n·เคลื่อนผ่านมิติ: ทริกเกอร์ผลนี้หลังจากเล่นการ์ดคำสั่งครั้งแรกในแต่ละเทิร์น, นำสำเนาต้นฉบับชั่วคราวของมันไปวางในมิติพิเศษและมอบ「สัญญาณจุดวิกฤติ」25 สะสมให้กับมันและสำเนาชั่วคราว, ไม่สามารถเปิดใช้ผลนี้ในเทิร์นอัลตร้า.\n·สัญญาณจุดวิกฤติ: ทุก 1 สะสมที่มีจะเพิ่มความเสียหาย, STR คงที่และความเสียหายจากหนวดสัมผัส, พิษคงที่, ผลสุดท้ายของการโต้กลับคงที่ 2%, ผลสุดท้ายของโล่คงที่, การฟื้นฟู HP คงที่, STR▼ 1%, และจะถูกลบออกหลังจากเล่น. การ์ดที่มีสัญญาณจุดวิกฤติไม่สามารถทริกเกอร์「เคลื่อนผ่านมิติ」ได้.\n·มิติพิเศษ: เมื่อมิติพิเศษถึงขีดจำกัด สิ้นสุดเทิร์นจะเปลี่ยนเป็นการเปิดใช้มิติพิเศษ: จะไม่ได้รับเทิร์นพิเศษอีกต่อไป, ทิ้งไพ่บนมือที่ไม่ได้เก็บรักษาและทริกเกอร์ผลสุญญตา, นำการ์ดทั้งหมดในมิติพิเศษมาวางในมือ, ตั้งค่าอริธเมทิกาปัจจุบันเป็น 5 จุด. หลังจากเปิดใช้มิติพิเศษ เทิร์นนี้จะถือว่าเป็นเทิร์นอัลตร้า.\n·「ทำลายล้างเอกภาวะ」: นำการ์ดซ้ายสุดในมิติพิเศษออกมา. คูลดาวน์ 3 เทิร์น.\n·หลังจากเริ่มการสำรวจ DMG Amp. ของทีม +50% และได้รับ「ปริซึมจุดเอกฐาน」15 สะสม.\n·「ปริซึมจุดเอกฐาน」: การ์ดคำสั่งทั้งหมดถือว่ามีโบนัสสัญญาณจุดวิกฤติในจำนวนเท่ากัน.\n·มิติพิเศษเชี่ยวชาญ: ทุก 1 จุดความชำนาญดินแดนของทีม จะเพิ่มจำนวนสะสม「สัญญาณจุดวิกฤติ」ที่「ปริซึมจุดเอกฐาน」และ「เคลื่อนผ่านมิติ」มอบให้ 0.05％.\n·บริสุทธิ์สูงสุดมิติพิเศษ: หากทีมประกอบด้วยผู้ปลุกตื่นอัลตร้าหรือเคออสเท่านั้น ผลมิติพิเศษเชี่ยวชาญและ DMG Amp. ที่ดินแดนมอบให้จะเพิ่มเป็นสองเท่า."
  },
  AwakerTalent_127223_TalentName_1 = {
    Text = "สายใยแห่งโชคชะตา"
  },
  AwakerTalent_130395_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทดารา」เท่านั้น.\n·ร่างกายที่ตื่นขึ้น มีค่าพลังชีวิต,      การโจมตี,      และการป้องกันเพิ่มขึ้น [Arg1] % และเมื่อร่างกายที่ตื่นขึ้นใช้การตื่นรู้แห่งวิญญาณครั้งแรกจะได้รับพลังกุญแจเงิน [Arg2] หน่วย."
  },
