  },
  AwakerTalent_130398_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น\n·เพิ่ม CON, การโจมตี, และการป้องกันของร่างตื่นนี้ขึ้น [Arg1]％ และทำให้ร่างตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก\n·ร่างตื่นที่ถูกเลือกโดย「บทเพลงของซายะ」จะได้รับ「เทศกาลเพาะพันธุ์」[Arg3] ชั้น และทำให้คำสั่งกุญแจถัดไปมีผล 2 ครั้ง\n·「การกัดกร่อน」ที่ซายะสร้างต่อศัตรู「คาโร」จะเพิ่มขึ้นเพิ่มเติม [Arg4]％"
  },
  AwakerTalent_130398_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น\n·เพิ่ม CON, การโจมตี, และการป้องกันของร่างตื่นนี้ขึ้น [Arg1]％ และทำให้ร่างตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก\n·ร่างตื่นที่ถูกเลือกโดย「บทเพลงของซายะ」จะได้รับ「เทศกาลเพาะพันธุ์」[Arg3] ชั้น และทำให้คำสั่งกุญแจถัดไปมีผล 2 ครั้ง\n·「การกัดกร่อน」ที่ซายะสร้างต่อศัตรู「คาโร」จะเพิ่มขึ้นเพิ่มเติม [Arg4]％"
