  AwakerTalent_130400_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「星辰篇」เท่านั้น.\n·CON, การโจมตี, การป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] ％ และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] จุด หลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·「无边荒影」สร้างผล STR▼ และตัวคูณ STR ที่ได้รับเพิ่มขึ้น [Arg3]％, ทุกครั้งที่มีผลจะทำให้「染罪枪锋」ครั้งถัดไปได้รับโบนัส STR เพิ่มเติม [Arg4]％, สูงสุด 1200％."
  },
