  },
  AwakerTalent_130919_TalentDesc_1 = {
    Text = "·เมื่อตัวละครนี้อยู่ในทีม, จะแทนที่ดินแดน「เอควอ」ด้วยดินแดน「ห้วงอเวจี: เอควอ」.\n·ความเสียหายพื้นฐานจากหนวดสัมผัสเปลี่ยนเป็น 5% ของ Max HP ของทีม.\n·หลังจากเริ่มต้นการสำรวจ, DMG Amp. ของทีม+50%, หากทีมประกอบด้วยร่างตื่นเอควอหรือเคออสเท่านั้น, DMG Amp. ที่ได้รับจากผลนี้จะเพิ่มเป็นสองเท่า, แต่เมื่อเริ่มต้นการต่อสู้จะไม่ได้รับหนวดสัมผัสเพิ่มเติม.\n·ไม่มีผล「การรวมตัวของหนวดสัมผัส」อีกต่อไป.\n·ท่าทางหนวดสัมผัสเปลี่ยนเป็น「ท่าทางหนวดสัมผัส·ห้วงอเวจี」.\n·「ห้วงอเวจี·คลื่นสงบ」: ได้รับโล่เท่ากับ 25% ของ Max HP, หลังสิ้นสุดเทิร์นหนวดสัมผัสจะไม่โจมตีอีก, คูลดาวน์ 3 เทิร์น.\n·「ห้วงอเวจี·คลื่นกระหน่ำ」: ทำให้ความเสียหายจากหนวดสัมผัสในเทิร์นนี้กลายเป็น 125%, หลังจากสร้างดาเมจสกิลกดใช้แล้วทำให้หนวดสัมผัส 1 เส้นโจมตี, แต่หลังสิ้นสุดเทิร์นจะสูญเสียหนวดสัมผัส 1 เส้น, คูลดาวน์ 3 เทิร์น.\n·ความชำนาญดินแดนเปลี่ยนเป็น「ความชำนาญในทะเลลึก·ห้วงอเวจี」, ทุก 1 จุดความชำนาญดินแดนทำให้โล่ของ「ห้วงอเวจี·คลื่นสงบ」เพิ่มขึ้น 0.025% ของ Max HP, และทำให้ความเสียหายจากหนวดสัมผัสของ「ห้วงอเวจี·คลื่นกระหน่ำ」เพิ่มขึ้นเพิ่มเติม 0.025%.\n·หากทีมประกอบด้วยร่างตื่นเอควอหรือเคออสเท่านั้น, ผล「ความชำนาญดินแดน·ห้วงอเวจี」จะเพิ่มเป็นสองเท่า."
  },
  AwakerTalent_130919_TalentName_1 = {
    Text = "ดินแดนแห่งความมืดนิรันดร์"
  },
  AwakerTalent_130920_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「星辰篇」เท่านั้น.\n·CON, การโจมตี, การป้องกัน ของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] ％ และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] จุด หลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·ความเสียหายคงที่ของ「กระสุนวน!」เพิ่มขึ้น [Arg3]％.\n·มอสจะลบผล「เสริมความแข็งแกร่ง」และ「เสริมความแข็งแกร่งชั่วคราว」ของเป้าหมายก่อนปล่อยระเบิดพลัง, หากลบสำเร็จ ดาเมจคริติคอลของการระเบิดพลังครั้งนี้ + [Arg4]％."
