  },
  AwakerTalent_141303_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น\n·CON, โจมตี, การป้องกันของร่างตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ร่างตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก\n·ความเสียหายคงที่ที่「พอนโทส」สร้างให้「Familier ปิติสุข」เพิ่มขึ้น [Arg3]％\n·「ระเริงล่าสังหารไร้สิ้นสุด」ทุกการสิ้นเปลือง 10 คะแนนอาลีมัสจะได้รับความเสียหายจากหนวดสัมผัสเท่ากับ [Arg4]％ ของ ATK,「ฝูงกอนท์จู่โจม」เมื่อสร้างความเสียหายจะลด STR ของเป้าหมายลงชั่วคราว [Arg5]％ ของ DEF"
  },
  AwakerTalent_141303_TalentDesc_10 = {
