    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น\n·CON, การโจมตี, และการป้องกันของร่างตื่นนี้เพิ่มขึ้น [Arg1] %, และหลังจากที่ร่างตื่นนี้เล่นวิญญาณตื่นรู้เป็นครั้งแรกจะได้รับพลังงานกุญแจเงิน [Arg2] แต้ม\n·「คมดาบสะบั้นมิติ」ได้รับโบนัส STR เพิ่มเติม [Arg3]％, หลังจากสังหารศัตรูจะได้รับ [Arg4] รอยดำ, ได้รับโบนัสอัตราดรอปผนึกขี้ผึ้งสีนิลของตัวเอง, มีผลสูงสุด 1 ครั้งต่อการต่อสู้"
  },
