  AwakerTalent_145718_TalentDesc_1 = {
    Text = "·เมื่อ คาราบู อยู่ในทีม จะแทนที่ดินแดน「คาโร」ด้วยดินแดน「แพร่พันธุ์: คาโร」\n·หลอมรวมตัวอ่อน: การหลอมรวมตัวอ่อนที่ได้รับในแต่ละรอบเพิ่มขึ้นเป็น 50~100, เพิ่มขึ้นตาม HP ที่สูญเสียไป, แต่ขีดจำกัดการหลอมรวมของตัวอ่อนเพิ่มจาก 100 เป็น 200, เมื่อถึงขีดจำกัดจะวาง「เพาะพันธุ์ตัวอ่อน」ไว้ในมือ\n·เพาะพันธุ์ตัวอ่อน: เมื่อเล่นแล้วจะไม่ได้รับอัตราคริติคอลอีกต่อไป, และการกลืนกินก็จะไม่ได้รับโล่และ STR ชั่วคราวอีกต่อไป. ในแต่ละรอบเมื่อร่างตื่นแต่ละคนใช้「เพาะพันธุ์ตัวอ่อน」เป็นครั้งแรก จะได้รับ 40 ชั้น「เทศกาลเพาะพันธุ์」: ทุก 1 ชั้นที่มีอยู่จะเพิ่มผลสุดท้ายของความเสียหายจากการระเบิดพลังอาลีมัสครั้งถัดไปของร่างตื่นนั้นในรอบนี้, โล่คงที่, การฟื้นฟู HP คงที่, STR คงที่, STR▼, การเพิ่มความเสียหายจากหนวด, พิษคงที่, เคาน์เตอร์คงที่ ขึ้น 1％\n·เตาหลอมเลือด: ปริมาณสะสมอัตโนมัติเมื่อเริ่มต้นรอบเปลี่ยนเป็น 10% ของ HP ที่สูญเสียไป, ปริมาณสะสมสูงสุดเปลี่ยนเป็น 50% ของ Max HP. เมื่อสิ้นสุดการต่อสู้จะไม่สะสมอีกต่อไป, และมีคูลดาวน์ 3 รอบเมื่อใช้\n·การกัดเซาะสีแดง: หลังจากใช้เตาหลอมเลือดจะทำให้ศัตรูทั้งหมดได้รับการกัดกร่อน 1% ของ Max HP ของเป้าหมาย, ยิ่งใช้เตาหลอมเลือดมากเท่าไหร่เอฟเฟกต์การกัดกร่อนก็ยิ่งแรงขึ้น สูงสุดเพิ่มขึ้น 100%. สร้างเอฟเฟกต์การกัดกร่อน 5 เท่าต่อศัตรู「เปลือกเปล่า」\n·หลังจากเริ่มต้นการสำรวจ Max HP เพิ่มขึ้น 10％, DMG Amp. ของทีม +50%, เมื่อเริ่มต้นแต่ละรอบร่างตื่นทั้งหมดจะได้รับ 20 ชั้น「เทศกาลเพาะพันธุ์」. หากทีมประกอบด้วยร่างตื่นแห่งคาโรหรือตัวปลุกแห่งความวุ่นวายเท่านั้น, DMG Amp. ที่ได้รับจากเอฟเฟกต์นี้จะเพิ่มเป็นสองเท่า\n·ความชำนาญดินแดนจะเปลี่ยนเป็น「การเชี่ยวชาญแพร่พันธุ์·คาโร」, ทุก 1 แต้มความชำนาญดินแดนจะเพิ่ม「เทศกาลเพาะพันธุ์」ที่ได้รับจาก「แพร่พันธุ์: คาโร」ขึ้น 0.05%\n·หากทีมประกอบด้วยร่างตื่นแห่งคาโรหรือตัวปลุกแห่งความวุ่นวายเท่านั้น, เอฟเฟกต์「การเชี่ยวชาญแพร่พันธุ์·คาโร」จะเพิ่มเป็นสองเท่า"
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "ดินแดนบริสุทธิ์แห่งการเพาะพันธุ์"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "·เมื่อ โลธัน: เทพวาฬเวหา อยู่ในทีม จะแทนที่ดินแดน「เคออส」ด้วยดินแดน「ปฐมกาล: เคออส」\n·สายธารปฐมกาล: พลังงานกุญแจเงินพื้นฐานเพิ่มเป็น 2000 จุด, DMG Amp. ของทีม +50%, การโจมตีและการป้องกันของผู้ปลุกตื่นทุกคนเพิ่มขึ้น 10%. หากทีมประกอบด้วยตัวปลุกแห่งความวุ่นวายเท่านั้น DMG Amp. ที่ได้รับจากผลนี้จะเพิ่มเป็นสองเท่า. เมื่อเริ่มต้นการต่อสู้ จะได้รับพลังงานกุญแจเงิน 2000 จุด.\n·กุญแจหมื่นบรรจบ: ระดับชาร์จกุญแจเงินของผู้ปลุกตื่นทุกคนจะเปลี่ยนเป็นค่าเฉลี่ยของทีม. และจะไม่ได้รับพลังงานกุญแจเงินจากแต้มอริธเมทิกาอีกต่อไป แต่การ์ดคำสั่งใบแรกของแต่ละผู้ปลุกตื่นในแต่ละเทิร์นจะได้รับพลังงานกุญแจเงิน「ระดับชาร์จกุญแจเงินของผู้ปลุกตื่นนั้น×3+100」.\n·ดินแดนไร้การแบ่งแยก: จะไม่ทริกเกอร์ผล บริสุทธิ์สูงสุดมิติพิเศษ, ความชำนาญดินแดนเพิ่มเป็นสองเท่า, Amp. เพิ่มเป็นสองเท่าของดินแดนอื่นอีกต่อไป.\n·เสียงสะท้อนปฐมกาล: วิญญาณตื่นรู้จะได้รับเตรียมพร้อม 1, เมื่อเล่นครั้งแรกในแต่ละเทิร์นจะปล่อยคำสั่งกุญแจที่พกพาอยู่โดยอัตโนมัติ.\n·ความทรงจำแตกสลาย: คำสั่งกุญแจจะถูกแทนที่ด้วย「ปฐมกาล·คู่แฝดหวนคืน」และ「ปฐมกาล·วิวรณ์สามประการ」, คำสั่งกุญแจที่พกพาอยู่เองไม่สามารถปล่อยได้.\n·ปฐมกาล · คู่แฝดหวนคืน: ค้นพบคำสั่งกุญแจ 3 ชนิดจากคำสั่งกุญแจที่ถือครองอยู่, เลือก 1 คำสั่งกุญแจเพื่อให้มีผล 2 ครั้ง.\n·ปฐมกาล · วิวรณ์สามประการ: ค้นพบคำสั่งกุญแจ 3 ชุดจากคำสั่งกุญแจที่ถือครองอยู่, แต่ละชุดประกอบด้วยคำสั่งกุญแจ 3 ชนิดที่แตกต่างกัน, เลือกหนึ่งชุดเพื่อให้คำสั่งกุญแจในชุดนั้นมีผลตามลำดับ 1 ครั้ง.\n·คำสั่งกุญแจใน ปฐมกาล·คู่แฝดหวนคืน และ ปฐมกาล·วิวรณ์สามประการ จะรวมถึง「ความทรงจำแรกเริ่ม」แปดชนิด.\n·ปฐมกาล·คู่แฝดหวนคืน และ ปฐมกาล·วิวรณ์สามประการ ถือว่าปล่อยคำสั่งกุญแจเพียง 1 ครั้ง, เมื่อมีผลหลายครั้งจะมีผลเฉพาะกับคำสั่งกุญแจแรกที่มีผลเท่านั้น.\n·ความชำนาญดินแดนจะเปลี่ยนเป็น「ความเชี่ยวชาญแห่งความวุ่นวายปฐมกาล」, ทุก 1 จุดความชำนาญดินแดนจะเพิ่มความแรงของคำสั่งกุญแจ 0.05％.\n·ทุก 1 จุดความแรงของคำสั่งกุญแจจะเพิ่มพิษคงที่, การโต้กลับคงที่, STR คงที่, ความเสียหายจากหนวดสัมผัสคงที่, เถ้าถ่านเก่าคงที่ 2%, เพิ่มโล่คงที่, การฟื้นฟู HP คงที่, STR▼, อัตราคริติคอล, ดาเมจคริติคอล, DMG Amp., ความชำนาญดินแดน, อาลีมัส, หลอมรวมตัวอ่อน, พลังงานกุญแจเงิน 1%.\n·หากทีมประกอบด้วยตัวปลุกแห่งความวุ่นวายเท่านั้น ผล「ความเชี่ยวชาญแห่งความวุ่นวายปฐมกาล」จะเพิ่มเป็นสองเท่า."
  },
