  AwakerTalent_44845_TalentDesc_1 = {
    Text = "·ลิลลี่ตัวเองและอุปกรณ์ วงล้อมชีวิตและพันธสัญญา ทุก 1% ของการต่อต้านความตาย จะทำให้โล่พื้นฐานของ 「หนองน้ำอาถรรพ์」 และ 「การป้องกันพื้นฐาน」 เพิ่มขึ้น 0.25% และในการต่อสู้กับผู้นำ ปริมาณการสะสมและขีดจำกัดของความอดทนจะเพิ่มขึ้น 0.25%。\n·เมื่อมีลิลลี่อยู่ในทีม ทุกครั้งที่สูญเสียชีวิต 1 หน่วย จะได้รับ 1 ระดับความอดทน ขีดจำกัดการสะสมของความอดทนเท่ากับพลังชีวิตสูงสุด。"
  },
