  AwakerTalent_46445_TalentDesc_1 = {
    Text = "·เตาหลอมที่ซัลวาดอร์ให้จะได้รับผลการฟื้นฟูพลังที่เพิ่มขึ้นจากการฟื้นฟูชีวิต"
  },
  AwakerTalent_46445_TalentName_1 = {
    Text = "ผู้เลี้ยงวิญญาณ"
  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "·ราโมน่าได้รับคุณสมบัติการชาร์จกุญแจเงินเพิ่มเติม 2.5 คะแนน ทุกระดับอัตราการประสานจะทำให้ราโมน่าได้รับคุณสมบัติการชาร์จกุญแจเงินเพิ่มเติม 0.5 คะแนน。\n·ทุกครั้งที่มีคุณสมบัติระดับการชาร์จกุญแจเงิน 1 คะแนน จะทำให้ความเสียหายพื้นฐานของ「คมดาบราชินี」เพิ่มขึ้น 1 % หลังจากเล่นจะได้รับความชำนาญดินแดนชั่วคราว 0.75 คะแนน。"
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "การสั่นสะเทือนของหัวใจและเงิน"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "·ราโมน่า: วัฏกาล ได้รับคุณสมบัติการชาร์จกุญแจเงินเพิ่มอีก 2.5 คะแนน สำหรับแต่ละระดับอัตราการประสานจะทำให้ราโมน่า: วัฏกาลได้รับคุณสมบัติการชาร์จกุญแจเงินเพิ่มอีก 0.5 คะแนน。\n·สำหรับทุก 1 คะแนนคุณสมบัติการชาร์จกุญแจเงิน จะทำให้ผลกระทบการลูปของ「การโจมตีพื้นฐาน」ทำให้ราโมน่า: วัฏกาลได้รับอัตราคริติคอล 0.2% และผลกระทบการลูปของ「การป้องกันพื้นฐาน」ทำให้ราโมน่า: วัฏกาลได้รับอาลีมัส 0.2。"
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "การสั่นสะเทือนของหัวใจและเงิน"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "·น็อตทิล่ามีความชำนาญในดินแดนเพิ่มขึ้น 1 จุด จะทำให้การตอบโต้จาก \"พร้อมและตั้ง\" เพิ่มขึ้น 0.25%"
  },
  AwakerTalent_49872_TalentName_1 = {
    Text = "การซ่อมบำรุง"
  },
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "·นิมเฟียมีคุณสมบัติความแรงของดาเมจเพิ่มขึ้น 1% จะทำให้ผลของพิษพื้นฐานจาก「ระฆังโศกดังก้อง」และ「พิธีศพแห่งตน」เพิ่มขึ้น 0.5%。"
  },
  AwakerTalent_49873_TalentName_1 = {
    Text = "การติดเชื้อ"
  },
  AwakerTalent_51744_TalentDesc_1 = {
    Text = "·เมื่อการต่อสู้เริ่มต้นขึ้น ให้วางการ์ด「หลงผิด」1 ใบลงในมือ.\n·มิเรียมจะได้รับโบนัสความเสียหายจากหนวด 100% สำหรับ「การตีพื้นฐาน」ของเธอ.\n·มิเรียมผู้ปลุกตื่น,      วงล้อมชีวิต,      และพันธสัญญาจะเพิ่มขึ้น 0.2% สำหรับพละกำลังของการระเบิดพลัง,      ความเสียหายจากหนวด,      อาลีมัส,      และการใช้และกระตุ้นผลพิษ สำหรับทุกๆ 1% ของดาเมจคริติคอลที่ให้."
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "ความศรัทธาที่ไม่เสื่อมสลาย"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "·ธูลูเอง วงล้อมชีวิตที่ติดตั้งและพันธสัญญาแต่ละอันให้ระดับการชาร์จความคลั่ง 1 หน่วย จะทำให้「ตีพื้นฐาน」ได้รับความเสียหายจากหนวด 5% และพละกำลังเพิ่มขึ้น และ「บัญชาห้วงลึก」ได้รับความเสียหายจากหนวด 15% และพละกำลังเพิ่มขึ้น。"
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "พลังของพระเจ้าผู้เป็นเทพ"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "·ซังก้าตัวเองและอุปกรณ์ วงล้อมชีวิตและพันธสัญญา ทุก 1% ของการต่อต้านความตายจะทำให้ความคลั่งที่ได้รับจาก「การโจมตีพื้นฐาน」และ「การป้องกันพื้นฐาน」เพิ่มขึ้น 0.03 คะแนน และ「ศิลป์เร้นสูญ」จะได้รับอัตราคริติคอลและโบนัสความเสียหายเพิ่มเติม 0.15%。"
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "แรงบันดาลใจจากความตาย"
  },
  AwakerTalent_54047_TalentDesc_1 = {
    Text = "·ผลการฟื้นฟูของ \"ศึกษา\" และ \"ศัลยกรรมภายนอก\" เพิ่มขึ้น 0.5% ต่อระดับการฟื้นฟูอาลีมัสทุก 1 จุดที่ตุ๊กตาได้รับ"
  },
  AwakerTalent_54047_TalentName_1 = {
    Text = "การถอดแยกลิงจี้"
  },
  AwakerTalent_54072_TalentDesc_1 = {
    Text = "·โอเกียร์จะได้รับเงินรางวัลคูณ 1% จากผลการตกของสัญลักษณ์ดำทุก 1% กับการเพิ่มพละกำลังชั่วคราวจาก 「เจ็ดศิลป์ สรรค์คุณธรรม」เพิ่มขึ้น 3%。"
  },
  AwakerTalent_54072_TalentName_1 = {
    Text = "การแปลงรูปแบบไม่มีรูปร่าง"
  },
  AwakerTalent_54073_TalentDesc_1 = {
    Text = "·อัลวาเมื่อมีคุณสมบัติการต่อต้านความตาย 1% ความเสียหายพื้นฐานจะเพิ่มขึ้น 0.5%."
  },
  AwakerTalent_54073_TalentName_1 = {
    Text = "มุมมองแบบไดนามิก"
  },
