  AwakerTalent_54158_TalentDesc_1 = {
    Text = "·โซเรลตัวเองและอุปกรณ์ วงล้อมชีวิตและพันธสัญญาทุก 1% ของอัตราคริติคอล จะทำให้ความคลั่งที่ได้รับจาก「การป้องกันพื้นฐาน」เพิ่มขึ้น 0.2。"
