  AwakerTalent_54158_TalentName_1 = {
    Text = "ผู้พิทักษ์ความหรูหรา"
  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "·เซนคินปลุกเร้าร่างกาย ตำแหน่งล้อชะตา และการบรรลุแต่ละครั้งที่เพิ่มอัตราคริติคอล 1% จะเพิ่มความเสียหายพื้นฐานของ 「การโจมตีพื้นฐาน」 และ 「บราวน์ออกปฏิบัติการ」 ขึ้น 2%"
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "ร่วมมือต่อต้านศัตรู"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "·เอริกาผู้ปลุกตื่นตนเอง, วงล้อมชีวิต, พันธสัญญาแต่ละชิ้นจะมอบคุณสมบัติระดับชาร์จกุญแจเงิน 1 คะแนน, 「ระเบิดแม่เหล็กไฟฟ้า」จะทำให้เอริกาได้รับอัตราการคริติคอลชั่วคราว 0.5% และดาเมจคริติคอล。"
  },
  AwakerTalent_55176_TalentName_1 = {
    Text = "แหล่งพลังงานภายนอก"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "·เมื่อเริ่มต้นรอบ ได้รับ 1 ชั้นฝันชักนำ。\n·ทุกครั้งที่ใช้ 1 ชั้นฝันชักนำ ทำให้「ผูู้ปกปักษ์การหลงหาย」และ「สุสานแห่งความฝัน」ที่ได้รับการโต้กลับเพิ่มพูนพลังโจมตี 5%。\n·ผู้ปลุกตื่นวานด้า, วงล้อมชีวิต, และพันธสัญญาทุก 1% ที่ให้คุณสมบัติความเสียหายแรงขึ้น จะทำให้การโต้กลับที่「สุสานแห่งความฝัน」ได้รับเพิ่มขึ้น 0.75%。"
  },
  AwakerTalent_55202_TalentName_1 = {
    Text = "การเปิดเผย"
  },
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "·คาเซียห์ผู้ปลุกตื่นตัวเอง วงล้อมชีวิต และพันธสัญญาทุก 1 คะแนนของความชำนาญดินแดน จะทำให้ความเสียหายพื้นฐานทั้งหมดของคาเซียห์เพิ่มขึ้น 0.2%。"
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "มาสเตอร์มายากล"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "·ทิงค์ผู้ปลุกตื่นแต่ละคน วงล้อมชีวิต และพันธสัญญาจะเพิ่มอัตราดรอปผนึกขี้ผึ้งสีนิล 1% จะทำให้「แสงเหนือพร่างดาว」ได้รับอัตราการคริติคอลชั่วคราวเพิ่มขึ้น 0.15%。"
  },
  AwakerTalent_55507_TalentName_1 = {
    Text = "นักเดินทางระหว่างดวงดาว"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "·บทกวี「การโจมตีพื้นฐาน」และ「การป้องกันพื้นฐาน」ของฮอร์ลายังถือว่าเป็นบทกวีอย่างหนึ่ง เมื่อบทกวีวาร์ปจะเปลี่ยนอารมณ์ไปสู่ความรู้สึกที่แตกต่าง ซึ่งอารมณ์สามารถส่งผลโดยตรงต่อผลของบทกวีนี้ สถานะอารมณ์ที่แตกต่างกันจะนำมาซึ่งผลกระทบที่ต่อเนื่องของทีมที่แตกต่างกัน。\n·ฮอร์ล่า จะได้รับการเพิ่มค่าผลกระทบตามค่าเริ่มต้น 0.1% สำหรับทุก 1% ของการต่อต้านความตายที่มีอยู่。"
  },
  AwakerTalent_55837_TalentName_1 = {
    Text = "ปากกาสร้างความรู้สึก"
  },
  AwakerTalent_56174_TalentDesc_1 = {
    Text = "·ฟารอสทุกๆ 1% ความแข็งแกร่งในการโจมตี，จะทำให้「เมืองที่หายไป」ที่สร้างโล่เพิ่มขึ้น 0.4%"
  },
  AwakerTalent_56174_TalentName_1 = {
    Text = "ความหลงใหลในการกลับบ้านเกิด"
  },
  AwakerTalent_56175_TalentDesc_1 = {
    Text = "·ซีคัสจะได้รับเงินรางวัลคูณ 1% จากผลการตกของสัญลักษณ์ดำทุก 1% กับการเพิ่มเคาน์เตอร์ของ 「การโจมตีพื้นฐาน」"
