  AwakerTalent_56223_TalentDesc_1 = {
    Text = "·เซเลสเท หลังจากเล่นการ์ดคำสั่งจะกระตุ้นหนวดสัมผัส 1 เส้นโจมตีศัตรู เซเลสเทตัวเอง,      วงล้อมชีวิต,      พันธสัญญาทุกๆ 1 คะแนนความชำนาญดินแดน จะทำให้การกระตุ้นครั้งนี้สร้างความเสียหายจากหนวด 0.5%."
