  AwakerTalent_57336_TalentDesc_1 = {
    Text = "·ซัลวาดอร์มีคุณสมบัติการดรอปธาตุดำเพิ่มขึ้น 1% จะทำให้พลังชีวิตสูงสุดของเตาหลอมเลือดเพิ่มขึ้น 0.15%"
