  AwakerTalent_57408_TalentDesc_1 = {
    Text = "·อักริปปาตัวเอง, วงล้อมชีวิตและพันธสัญญาที่สวมใส่ทุกๆ 1% ของคุณสมบัติการดรอปธาตุดำ จะทำให้โล่พื้นฐานของ「การปกป้องซีด」เพิ่มขึ้น 0.5% และพิษพื้นฐานเพิ่มขึ้น 1%"
