  AwakerTalent_57419_TalentDesc_1 = {
    Text = "·เฟนท์ทุก 1% ของการต่อต้านความตาย จะทำให้「เปลเด็กแห่งดวงดารา」และ「ดาราไร้ขอบเขต」ได้รับการโต้กลับเพิ่มขึ้น 0.2% และขีดจำกัดการต่อต้านความตายของ「เปลเด็กแห่งดวงดารา」+2%"
