  },
  AwakerTalent_57567_TalentDesc_1 = {
    Text = "·เฮลอตมีคุณสมบัติความเสียหายเพิ่มขึ้น 1% 「การดิ้นรนในห้วงวิกฤต」จะทำให้ความเสียหายที่เฮลอตสร้างในรอบนี้เพิ่มขึ้น 0.3%。"
  },
  AwakerTalent_57567_TalentName_1 = {
    Text = "รอยแผลทรมาน"
  },
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "·ไรเกอร์สังหารศัตรูจะได้รับรอยดำ 5 ชิ้น ไรเกอร์จะเพิ่มการได้รับรอยดำขึ้น 1% สำหรับทุกๆ 1% ของอัตราดรอปผนึกขี้ผึ้งสีนิล สูงสุด 5 ครั้งต่อการสำรวจ\n·เมื่อได้รับรอยดำ 50/125/250 จากการต่อสู้ ขีดจำกัดสิ่งสร้างจะเพิ่มขึ้น +1 และเมื่อสิ้นสุดการต่อสู้ให้เลือก<C05_zaowu:「มรดกของความวุ่นวาย」>เพื่อเพิ่มในรายการสิ่งสร้าง."
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "ผู้ชนะได้ทุกอย่าง"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "·ในการต่อสู้กับผู้นำ เมื่อเริ่มต้นเทิร์นและหลังจาก「การหลอมละลาย · ดอร์」ปล่อยระเบิดพลัง จะได้รับ 1 ชั้นของ「ปลายทาง」。「ปลายทาง」สามารถมีได้สูงสุด 10 ชั้น เมื่อถึง 10 ชั้น จะเพิ่ม 1 ใบ「สุญญตาดับสูญ」ลงในมือ。"
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "ทางแห่งการการสูญพันธุ์"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」.\n·ผู้ปลุกตื่นนี้จะเพิ่มค่าร่างกาย การโจมตี และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากการตื่นรู้ครั้งแรกของวิญญาณ.\n·ทุกหนวดสัมผัสที่โจมตีจะเพิ่มความเสียหายชั่วคราวของหนวดสัมผัสขึ้น [Arg3]％ ของพลังโจมตีของธูลู โดยมีผลสูงสุด [Arg4] ครั้งต่อรอบ.\n·เมื่อในทีมมีผู้ปลุกตื่น「ลิโมเรีย」อื่นอีก 1/2/3 คน ศัตรูทั้งหมดจะได้รับความเสียหายจากหนวดสัมผัสเพิ่มขึ้น 10％/25％/50％."
  },
  AwakerTalent_74099_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」.\n·ผู้ปลุกตื่นนี้จะเพิ่มค่าร่างกาย การโจมตี และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากการตื่นรู้ครั้งแรกของวิญญาณ.\n·ทุกหนวดสัมผัสที่โจมตีจะเพิ่มความเสียหายชั่วคราวของหนวดสัมผัสขึ้น [Arg3]％ ของพลังโจมตีของธูลู โดยมีผลสูงสุด [Arg4] ครั้งต่อรอบ.\n·เมื่อในทีมมีผู้ปลุกตื่น「ลิโมเรีย」อื่นอีก 1/2/3 คน ศัตรูทั้งหมดจะได้รับความเสียหายจากหนวดสัมผัสเพิ่มขึ้น 10％/25％/50％."
  },
