    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」.\n·ผู้ปลุกตื่นนี้จะเพิ่มค่าร่างกาย การโจมตี และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากการตื่นรู้ครั้งแรกของวิญญาณ.\n·ทุกหนวดสัมผัสที่โจมตีจะเพิ่มความเสียหายชั่วคราวของหนวดสัมผัสขึ้น [Arg3]％ ของพลังโจมตีของธูลู โดยมีผลสูงสุด [Arg4] ครั้งต่อรอบ.\n·เมื่อในทีมมีผู้ปลุกตื่น「ลิโมเรีย」อื่นอีก 1/2/3 คน ศัตรูทั้งหมดจะได้รับความเสียหายจากหนวดสัมผัสเพิ่มขึ้น 10％/25％/50％."
