  AwakerTalent_74100_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON,      การโจมตี,      การป้องกัน ขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก.\n·ผลลดพลังของ「เฟนต์」เพิ่มขึ้น [Arg4] %.หลังจากเล่นการ์ดคำสั่งของ「เฟนต์」จะขโมยพลังชั่วคราวจากศัตรู「มนุษย์」เท่ากับ [Arg3]％ ของพลังโจมตีเฟนต์ มีผลสูงสุด 3 ครั้งต่อรอบ."
  },
