  AwakerTalent_74101_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะมี CON,      การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·ตราดำที่เลคได้รับด้วยตนเองเพิ่มขึ้น [Arg4]％ อัตราคริติคอลเพิ่มขึ้น [Arg3]％ หากได้รับตราดำอย่างน้อย 400 จากการต่อสู้ จะอัปเกรด「มรดกแห่งความโกลาหล」1 ชิ้นเมื่อเริ่มการต่อสู้."
