    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะมี CON,      การโจมตี,      การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·ในแต่ละรอบเมื่อเล่นการ์ดแรก「วังวนสีซีด」จะทำให้การหลอมรวมตัวอ่อน + [Arg3] และเมื่อกระตุ้นการกลืนกินจะทำให้การใช้พลังการคำนวณของการ์ด「วังวนสีซีด」ในมือ 1 ใบลดลง 1."
