  AwakerTalent_74104_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมี CON, ATK, DEF เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก。\n·เมื่อเริ่มต้นการต่อสู้ จะได้รับพละกำลัง [Arg3] % จากการโจมตีของเอริกา และการป้องกัน [Arg4] % จากการระวังภัยของเอริกา。"
  },
  AwakerTalent_74104_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON, ATK และ DEF จำนวน [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก。\n·เมื่อเริ่มต้นการต่อสู้ จะได้รับพละกำลังของเอริกาจำนวน [Arg3]％ และการป้องกันของเอริกาจำนวน [Arg4]％。"
  },
  AwakerTalent_74104_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่มค่าร่างกาย การโจมตี และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·เมื่อเริ่มต้นการต่อสู้ จะได้รับพละกำลังของเอริกาที่โจมตี [Arg3]％ และการป้องกันของเอริกาที่ระวังภัย [Arg4]％。"
  },
  AwakerTalent_74104_TalentDesc_3 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่า CON, ATK, DEF เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก。\n·เมื่อเริ่มต้นการต่อสู้ จะได้รับพละกำลัง [Arg3] % ของการโจมตีของเอริกาและการป้องกัน [Arg4] % ของการระวังภัยของเอริกา。"
  },
  AwakerTalent_74104_TalentDesc_4 = {
