    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่มค่าร่างกาย การโจมตี และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] เมื่อเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก。\n·เมื่อเริ่มต้นการต่อสู้ จะได้รับพละกำลังของเอริกาคือ [Arg3]％ และการป้องกันของเอริกาคือ [Arg4]％。"
