  AwakerTalent_74109_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะได้รับค่าร่างกาย การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และเมื่อผู้ปลุกตื่นนี้เล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก จะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน。\n·การ์ด「บราวน์ออกปฏิบัติการ」ที่เล่นใน 10 ใบแรกในแต่ละเทิร์นจะไม่เพิ่ม「การประสานอริธเมทิกา」。\n·ความเสียหายที่เจนกินสร้างขึ้นจะเพิ่มขึ้นตามค่าการโจมตี [Arg3] %。"
  },
  AwakerTalent_74109_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มีค่า CON, ATK และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนเมื่อเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก。\n·การ์ด「บราวน์ออกปฏิบัติการ」 10 ใบแรกที่เล่นในแต่ละเทิร์นจะไม่เพิ่มการประสานอริธเมทิกา。\n·ความเสียหายที่เจนกินทำให้เพิ่มขึ้น [Arg3]％ ของ ATK。"
  },
  AwakerTalent_74109_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมี CON, ATK, การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน หลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก。\n·การ์ด「บราวน์ออกศึก」ที่เล่นใน 10 ใบแรกในแต่ละเทิร์นจะไม่เพิ่มการประสานอริธเมทิกา。\n·เจนกินทำให้ความเสียหายเพิ่มขึ้นตาม ATK จำนวน [Arg3] %。"
  },
  AwakerTalent_74109_TalentDesc_3 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่า CON, ATK, การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนเมื่อเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก。\n·การเล่น「บราวน์ออกมา」 10 ใบแรกในแต่ละเทิร์นจะไม่เพิ่มการประสานอริธเมทิกา。\n·เจนกินทำให้ความเสียหายเพิ่มขึ้น [Arg3]% ของ ATK。"
  },
  AwakerTalent_74109_TalentDesc_4 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON, ATK, การป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก。\n·การ์ด「บราวน์ออกเดินทาง」 10 ใบแรกที่เล่นในแต่ละเทิร์นจะไม่เพิ่มการประสานอริธเมทิกา。\n·เจนกินทำให้ความเสียหายเพิ่มขึ้น [Arg3]％ ของ ATK。"
  },
  AwakerTalent_74109_TalentDesc_5 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่มค่า CON, ATK และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน หลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·การ์ด「บราวน์ออกปฏิบัติการ」ที่เล่นใน 10 ใบแรกในแต่ละเทิร์นจะไม่เพิ่มการประสานอริธเมทิกา。\n·เจนกินทำความเสียหายเพิ่มขึ้น [Arg3] % ของค่า ATK。"
  },
  AwakerTalent_74109_TalentDesc_6 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」\n·ค่าร่างกาย การโจมตี และการป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน หลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก\n·การเล่น「บราวน์ออกเดินทาง」 10 ใบแรกในแต่ละเทิร์นจะไม่เพิ่มการประสานอริธเมทิกา\n·ความเสียหายที่เจนกินสร้างขึ้นเพิ่มขึ้น [Arg3] % ของค่า ATK.。"
  },
  AwakerTalent_74109_TalentDesc_7 = {
