  AwakerTalent_74111_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะเพิ่มค่า CON,      การโจมตี,      การป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก.\n·เมื่อเริ่มการต่อสู้ หากมีศัตรู「สัตว์ร้าย」 พลังที่คาสเซียสร้างในการต่อสู้นี้จะเพิ่มขึ้น [Arg3]％.หลังจากปล่อย「หายไปให้หมด」ครั้งแรกในแต่ละเทิร์น จะกระตุ้นเอฟเฟกต์คลื่นสะท้อนของการ์ดที่สับเข้ากองจั่ว."
  },
