  AwakerTalent_74112_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON,      การโจมตี และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก.\n·เมื่อซานสร้างโล่ จะได้รับความเสียหายหนวดสัมผัสเท่ากับ [Arg3]％ ของค่าโล่ เมื่อซานปล่อยการระเบิดพลังบ้าคลั่ง จะได้รับโบนัสความเสียหายหนวดสัมผัสเพิ่มเติม [Arg4]％."
  },
