  AwakerTalent_74113_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「星辰篇」เท่านั้น.\n·CON, การโจมตี, การป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] ％ และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] จุด หลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·「แส้สั่งการบ้าคลั่ง」ได้รับเก็บรักษาและเตรียมพร้อม. ศัตรูที่ตั้งใจจะสร้างความเสียหายจะรับดาเมจสกิลกดใช้ของแพนเดียเพิ่มขึ้น [Arg3]％, เพิ่มขึ้น 5％ ต่อการโจมตีเพิ่มเติมแต่ละครั้งของเป้าหมาย, สูงสุดเพิ่มได้ 20％."
  },
