  AwakerTalent_74114_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้ใช้ได้เฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON, การโจมตี และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก。\n·ไอจิสจะได้รับพลังกุญแจเงินที่ฟื้นฟูพลังงานกุญแจเงินของไอจิส [Arg3] % หลังจากเล่นการ์ดคำสั่งใบแรกในแต่ละเทิร์น。"
  },
  AwakerTalent_74114_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON, การโจมตี, การป้องกัน ขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน หลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก。\n·ไอจิสจะได้รับพลังงานกุญแจเงินจากการฟื้นฟูพลังงานกุญแจเงินของไอจิส จำนวน [Arg3] % หลังจากเล่นการ์ดคำสั่งใบแรกในแต่ละเทิร์น。"
  },
  AwakerTalent_74114_TalentDesc_2 = {
