  AwakerTalent_74115_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะได้รับ CON, การโจมตี, การป้องกัน เพิ่มขึ้น [Arg1] % และเมื่อผู้ปลุกตื่นนี้เล่นการตื่นรู้ทางจิตวิญญาณครั้งแรกจะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน。\n·ในแต่ละรอบ การเล่น「แผดเสียงร่ำร้อง เลือด」ก่อนหน้า [Arg3] ใบจะไม่เพิ่ม「การประสานอริธเมทิกา」。อูฟฮาชจะทำความเสียหายพื้นฐานเพิ่มขึ้น [Arg4]% เมื่อ HP ต่ำกว่า 25% จะทำให้ผลกระทบเพิ่มขึ้นเป็นสองเท่า。"
  },
  AwakerTalent_74115_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่า CON, โจมตี, การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·การเล่น「แผดเสียงร่ำร้อง เลือด」ก่อนหน้า [Arg3] ครั้งในแต่ละรอบจะไม่เพิ่ม「การประสานอริธเมทิกา」。อูฟฮาชจะมีความเสียหายพื้นฐานเพิ่มขึ้น [Arg4] % และเมื่อ HP ต่ำกว่า 25% จะมีผลคูณสอง。"
  },
  AwakerTalent_74115_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้ได้รับค่า CON, การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·การเล่น「แผดเสียงร่ำร้อง เลือด」ใน  [Arg3] รอบแรกจะไม่เพิ่ม「การประสานอริธเมทิกา」ความเสียหายพื้นฐานที่อูฟฮาชก่อให้เกิดเพิ่มขึ้น [Arg4]％ และเมื่อ HP ต่ำกว่า 25％ จะทำให้ผลลัพธ์เพิ่มเป็นสองเท่า。"
  },
  AwakerTalent_74115_TalentDesc_3 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทดารา」เท่านั้น \n·เพิ่มค่าพลังร่างกาย, โจมตี, และการป้องกันของร่างกายที่ตื่นขึ้นนี้ [Arg1]% และเมื่อร่างกายที่ตื่นขึ้นนี้ปล่อยท่าการตื่นรู้แห่งวิญญาณครั้งแรก จะได้รับพลังกุญแจเงิน [Arg2] หน่วย \n·「กรีดร้องเถอะ เลือด」จำนวน [Arg3] ใบแรกที่ใช้ในแต่ละรอบจะไม่เพิ่ม「การปรับความเข้ากันของพลังการคำนวณ」 ความเสียหายพื้นฐานของยูวฮะชิเพิ่มขึ้น [Arg4]% และเมื่อชีวิตต่ำกว่า 25% ผลจะเพิ่มเป็นสองเท่า"
  },
