    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้จะมีค่าร่างกาย การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากการตื่นรู้ด้วยวิญญาณ\n·การเล่น「แผดเสียงร่ำร้อง เลือด」  [Arg3] ใบแรกในแต่ละรอบจะไม่เพิ่ม「การประสานอริธเมทิกา」ความเสียหายพื้นฐานที่อูฟฮาชทำได้จะเพิ่มขึ้น [Arg4] % และเมื่อ HP ต่ำกว่า 25% จะทำให้ผลลัพธ์เพิ่มเป็นสองเท่า。"
