  AwakerTalent_74116_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมี CON, การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และเมื่อผู้ปลุกตื่นนี้เล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก จะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน。\n·ทาอิสเมื่อกลืนกินตัวอ่อน จะได้รับพลังงานกุญแจเงินที่ฟื้นฟูพลังงานกุญแจเงิน [Arg3] % และเมื่อกลืนกิน「บุตรบริสุทธิ์」ผลจะเพิ่มขึ้นเป็นสองเท่า。"
  },
  AwakerTalent_74116_TalentDesc_10 = {
