  AwakerTalent_74118_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้มีค่า CON,      การโจมตี,      การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก.\n·ความเสียหายพื้นฐานที่โกลิอาห์สร้างเพิ่มขึ้น [Arg3]％ 「พลังแห่งใบมีดยักษ์」ทำให้ความเสียหายสุดท้ายที่โกลิอาห์สร้างเพิ่มขึ้นชั่วคราว [Arg4]％.\n·เมื่อในทีมมีผู้ปลุกตื่น「ลิโมเรีย」อื่นอีก 1/2/3 คน ผู้ปลุกตื่นทั้งหมดจะได้รับผลการรับพลังเพิ่มขึ้นอีก 6%/15%/30%."
  },
  AwakerTalent_74118_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้มีค่า CON,      การโจมตี,      การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก.\n·ความเสียหายพื้นฐานที่โกลิอาห์สร้างเพิ่มขึ้น [Arg3]％ 「พลังแห่งใบมีดยักษ์」ทำให้ความเสียหายสุดท้ายที่โกลิอาห์สร้างเพิ่มขึ้นชั่วคราว [Arg4]％.\n·เมื่อในทีมมีผู้ปลุกตื่น「ลิโมเรีย」อื่นอีก 1/2/3 คน ผู้ปลุกตื่นทั้งหมดจะได้รับผลการรับพลังเพิ่มขึ้นอีก 6%/15%/30%."
  },
