  AwakerTalent_74119_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะมีค่า CON,      การโจมตี,      การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก.\n·เมื่อทาวีเล่นการ์ดที่เดิมเป็นของผู้ปลุกตื่นคนอื่นในทีม ผู้ปลุกตื่นที่เกี่ยวข้องจะเพิ่มความเสียหายสุดท้าย,      โล่,      การฟื้นฟูเลือดในเทิร์นนี้ขึ้น [Arg3]％ ไม่สามารถซ้อนทับได้."
