  AwakerTalent_74120_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น.\n·ค่าความต้านทาน,      การโจมตี,      และการป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนเมื่อทำการตื่นรู้ครั้งแรก.\n·ความเสียหายพื้นฐานที่เกิดจากการ์ดคำสั่งของโลทันเพิ่มขึ้น [Arg3]%.โลทันทุกครั้งที่ทำความเสียหาย 1 ครั้ง จะเพิ่มดาเมจสุดท้ายที่โลทันสร้างในเทิร์นนี้ขึ้น 5% สูงสุดเพิ่มขึ้น [Arg4]％."
  },
