    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะเพิ่มค่า CON,      โจมตี,      การป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากการเล่นวิญญาณตื่นรู้ครั้งแรก.\n·ผลลดพละกำลังที่เกิดจากผู้ปลุกตื่นทั้งหมดจะเพิ่มขึ้น [Arg3] %."
