  AwakerTalent_74122_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น\n·CON, โจมตี, การป้องกันของร่างตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ร่างตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก\n·หลังจากเล่น「ทำนองขับกังวาน」ทำให้ความเสียหายที่ศัตรูทุกตัวประเภท「มนุษย์รูป」สร้างลดลงชั่วคราว [Arg4]％ ไม่สามารถซ้อนกันได้. 「บทสวดส่งวิญญาณ」ได้รับอาลีมัส [Arg3] คะแนน และได้รับเพิ่มเติม 1 ครั้งต่อการขจัดสภาพลบ 1 ครั้ง"
  },
