  AwakerTalent_74123_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON,      โจมตี,      การป้องกัน ขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·ความเสียหายพื้นฐานที่「โจมตี」และ「คมดาบแห่งจิตตา」สร้างเพิ่มขึ้นเท่ากับ [Arg3]％ ของค่าเกราะที่ตัวเองได้รับในเทิร์นนี้ ความเสียหายสุดท้ายที่เอลวาสร้างต่อศัตรูอาณาจักร「เลือดเนื้อ」เพิ่มขึ้น [Arg4]％."
  },
