    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มีค่า CON,โจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก。\n·ความคลั่งที่ดอลล์สร้างขึ้น และผลการรักษาจากระเบิดพลังเพิ่มขึ้น [Arg3]％ และสำหรับผู้ปลุกตื่นในดินแดน「เคออส」อื่นๆ ในทีมอีก 1 คน จะทำให้ผลนี้เพิ่มขึ้นอีก [Arg4]％。"
  },
  AwakerTalent_74124_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้จะเพิ่มค่าร่างกาย, การโจมตี, และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับ [Arg2] คะแนนพลังงานกุญแจเงินหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก\n·ความคลั่งที่ดอลล์สร้างขึ้นและผลการรักษาจากระเบิดพลังเพิ่มขึ้น [Arg3]％ โดยในทีมมีผู้ปลุกตื่น「เคออส」ในดินแดนอื่น ๆ ทุกคนจะเพิ่มผลนี้ขึ้นอีก [Arg4]％。"
  },
  AwakerTalent_74124_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่าร่างกาย โจมตี การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] หลังจากเล่นวิญญาณตื่นรู้ครั้งแรก。\n·ดอลล์ทำให้ความคลั่งและการระเบิดพลังที่สร้างขึ้นมีผลการรักษาเพิ่มขึ้น [Arg3]％ และในทีมมีผู้ปลุกตื่นจาก「เคออส」ดินแดนอีก 1 คนจะทำให้ผลนี้เพิ่มขึ้นอีก [Arg4]％。"
  },
  AwakerTalent_74124_TalentDesc_3 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ค่าร่างกาย, การโจมตี, การป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] หลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก。\n·ความคลั่งที่ดอลล์สร้างขึ้นและผลการรักษาจากระเบิดพลังเพิ่มขึ้น [Arg3]％ และสำหรับผู้ปลุกตื่นในดินแดน「เคออส」ที่มีอยู่ในทีม 1 คน จะทำให้ผลนี้เพิ่มขึ้นอีก [Arg4]％。"
  },
  AwakerTalent_74124_TalentDesc_4 = {
