  AwakerTalent_74126_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้มีค่า CON,      การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก.\n·เอฟเฟกต์การได้รับพละกำลังของเรอาเพิ่มขึ้น [Arg4]％ หลังจากเล่น「การ์ดคำสั่ง」ของเรอา จะได้รับพละกำลังเท่ากับ [Arg3]％ ของพลังโจมตีเรอา เอฟเฟกต์นี้จะเพิ่มขึ้นตามเลือดที่สูญเสียไปในปัจจุบันสูงสุด 200％ มีผลสูงสุด 3 ครั้งต่อเทิร์น."
  },
