  AwakerTalent_74127_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะมี CON,      การโจมตี,      และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนเมื่อเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก.\n·ทุกๆ 1 ใบของ「อาหารมหัศจรรย์」ในมือ จะเพิ่มผลการฟื้นฟูพลังชีวิตและเกราะป้องกัน [Arg4]％ ซ้อนได้สูงสุด 3 ชั้น.ทุกครั้งที่เล่น「อาหารมหัศจรรย์」1 ครั้ง พิษที่เจียหลุนสร้างในการต่อสู้ครั้งนี้จะเพิ่มขึ้น [Arg3]％ ซ้อนได้สูงสุด 20 ชั้น."
  },
