  },
  AwakerTalent_74128_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะทำให้ค่า CON, การโจมตี, การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนเมื่อทำการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·ความเสียหายพื้นฐานที่เกิดจาก「24」จะเพิ่มขึ้น [Arg3]％ และความเสียหายสุดท้ายที่เกิดจากศัตรูใน「สมาคมนักประติมากรรม」จะเพิ่มขึ้น [Arg4]％。"
  },
  AwakerTalent_74128_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ความสามารถทางกายภาพ,การโจมตี,การป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] หลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก。\n·ความเสียหายพื้นฐานที่เกิดจาก「24」เพิ่มขึ้น [Arg3]％ และความเสียหายสุดท้ายที่เกิดจากการโจมตีศัตรู「สมาคมนักประติมากรรม」เพิ่มขึ้น [Arg4]％。"
  },
  AwakerTalent_74128_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้ใช้ได้เฉพาะในด่าน「บทของดวงดาว」\n·ร่างกายที่ปลุกตื่นนี้จะเพิ่มค่า CON, โจมตี, การป้องกัน [Arg1] % และทำให้ร่างกายที่ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก\n·ความเสียหายพื้นฐานที่เกิดจาก「24」เพิ่มขึ้น [Arg3]％ และความเสียหายสุดท้ายที่เกิดจากศัตรูใน「สมาคมนักประติมากรรม」เพิ่มขึ้น [Arg4]％。"
  },
  AwakerTalent_74128_TalentDesc_3 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」。\n·ผู้ปลุกตื่นนี้จะมีค่าร่างกาย การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] หลังจากการตื่นรู้ทางจิตวิญญาณครั้งแรก\n·ความเสียหายพื้นฐานที่เกิดจาก「24」เพิ่มขึ้น [Arg3]％ และความเสียหายสุดท้ายที่ทำให้กับศัตรู「สมาคมนักประติมากรรม」เพิ่มขึ้น [Arg4]％。"
  },
  AwakerTalent_74128_TalentDesc_4 = {
    Text = "·พรสวรรค์นี้ใช้ได้เฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ความสามารถ CON, การโจมตี, การป้องกัน ของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน หลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·ความเสียหายพื้นฐานที่เกิดจาก「24」เพิ่มขึ้น [Arg3] % และความเสียหายสุดท้ายที่เกิดกับศัตรูใน「สมาคมนักประติมากรรม」เพิ่มขึ้น [Arg4] %。"
  },
  AwakerTalent_74128_TalentDesc_5 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มีค่า CON,โจมตี,การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·ความเสียหายพื้นฐานที่เกิดจาก「24」จะเพิ่มขึ้น [Arg3]％ และความเสียหายสุดท้ายที่ทำให้ศัตรู「สมาคมนักประติมากรรม」จะเพิ่มขึ้น [Arg4]％。"
  },
