  AwakerTalent_74128_TalentDesc_8 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ค่าร่างกาย การโจมตี และการป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน หลังจากที่เล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·ความเสียหายพื้นฐานที่เกิดจาก「24」เพิ่มขึ้น [Arg3]％ และความเสียหายสุดท้ายที่ทำกับศัตรู「สมาคมนักประติมากรรม」เพิ่มขึ้น [Arg4]％。"
  },
  AwakerTalent_74128_TalentDesc_9 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」。\n·ความสามารถ CON, โจมตี, การป้องกัน ของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·ความเสียหายพื้นฐานที่เกิดจาก「24」เพิ่มขึ้น [Arg3] % และความเสียหายสุดท้ายที่เกิดขึ้นกับศัตรู「สมาคมนักประติมากรรม」เพิ่มขึ้น [Arg4] %。"
  },
