  AwakerTalent_74129_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะมีค่าร่างกาย การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนเมื่อเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก.\n·ความเสียหายสุดท้ายของ「โจมตี」ของลิลี่เพิ่มขึ้น [Arg3]％ ในการต่อสู้บอสจะเพิ่มเป็นสองเท่า.หลังจากถูกศัตรู「เหนือมิติ」โจมตี จะได้รับผลฟื้นฟูพลังชีวิตล่าช้า [Arg4]％ ของพลังชีวิตที่สูญเสียจากการโจมตีครั้งนี้.ผลเพิ่มความเสียหายของ「โจมตีตอบแทน」ตาม「อดทน」จะได้รับโบนัสเสริมความเสียหาย [Arg5]%."
  },
