  },
  AwakerTalent_74131_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON, การโจมตี, การป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·เลือก「การเหนี่ยวนำ」ใน「ซากปรักหักพังแห่งเถ้าถ่าน」จะทำให้ชีวิตสูงสุดเพิ่มขึ้น [Arg3]% ของชีวิตสูงสุดดีฟอลต์。"
  },
  AwakerTalent_74131_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มีค่า CON,โจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก。\n·หลังจากเลือก「การเหนี่ยวนำ」ใน「ซากปรักหักพังแห่งเถ้าถ่าน」จะทำให้ HP สูงสุดเพิ่มขึ้น [Arg3] % ของค่า HP สูงสุดเริ่มต้น。"
  },
  AwakerTalent_74131_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้ใช้ได้เฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON, โจมตี, การป้องกัน ขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·ใน「ซากปรักหักพังแห่งเถ้าถ่าน」หลังจากเลือก「การเหนี่ยวนำ」จะทำให้ Max HP เพิ่มขึ้น [Arg3]％ ของ Max HP เริ่มต้น。"
  },
  AwakerTalent_74131_TalentDesc_3 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่า CON, การโจมตี, การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากที่เล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·ใน「ซากปรักหักพังแห่งเถ้าถ่าน」เลือก「การเหนี่ยวนำ」จะทำให้ชีวิตสูงสุดเพิ่มขึ้น [Arg3]％ ของชีวิตสูงสุดเริ่มต้น。"
  },
