  AwakerTalent_74132_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะเพิ่มค่า CON,      การโจมตี และการป้องกันขึ้น [Arg1] % และจะได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากที่เล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก.\n·พิษที่ฟารอสสร้างขึ้นจะเพิ่มขึ้น [Arg3] %.เมื่อสิ้นสุดรอบใน「นครสาบสูญ」จะสั่งให้หนวดสัมผัสโจมตี 1 ครั้ง แต่การโจมตีเหล่านี้จะทำความเสียหายเพียง [Arg4]% เท่านั้น.\n·เมื่อในทีมมีผู้ปลุกตื่น「ลีมูเรีย」อื่นอีก 1/2/3 คน ความเสียหายเสริมพลัง +20%/50%/100％."
  },
