  AwakerTalent_74133_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่า CON, การโจมตี และการป้องกันสูงขึ้น [Arg1] % และจะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน หลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·การฟื้นฟูพลังงานกุญแจเงินของราโมน่าจะเพิ่มขึ้น [Arg3] % และจะได้รับพลังงานกุญแจเงินจำนวน [Arg4] % เมื่อเริ่มต้นการต่อสู้。"
  },
  AwakerTalent_74133_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่า CON, การโจมตี, การป้องกันเพิ่มขึ้น [Arg1] % และจะได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·การฟื้นฟูพลังงานกุญแจเงินของราโมน่าเพิ่มขึ้น [Arg3]％ และจะได้รับพลังงานกุญแจเงิน [Arg4]％ เมื่อเริ่มต้นการต่อสู้。"
  },
  AwakerTalent_74133_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มีค่า CON, การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก。\n·การฟื้นฟูพลังงานกุญแจเงินของราโมน่าเพิ่มขึ้น [Arg3]％ และได้รับพลังงานกุญแจเงิน [Arg4]％ ของการฟื้นฟูพลังงานกุญแจเงินเมื่อเริ่มต้นการต่อสู้。"
  },
  AwakerTalent_74133_TalentDesc_3 = {
    Text = "·พรสวรรค์นี้ใช้ได้เฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มีค่า CON, การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก。\n·การฟื้นฟูพลังงานกุญแจเงินของราโมน่าเพิ่มขึ้น [Arg3] % และเมื่อเริ่มต้นการต่อสู้จะได้รับพลังงานกุญแจเงิน [Arg4] %。"
  },
  AwakerTalent_74133_TalentDesc_4 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มีค่า CON, การโจมตี, การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้เมื่อเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรกจะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน。\n·การฟื้นฟูพลังงานกุญแจเงินของราโมน่าเพิ่มขึ้น [Arg3]％ และเริ่มต้นการต่อสู้จะได้รับพลังงานกุญแจเงินจำนวน [Arg4]％。"
  },
  AwakerTalent_74133_TalentDesc_5 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มีค่า CON, การโจมตี, การป้องกัน เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก。\n·การฟื้นฟูพลังงานกุญแจเงินของราโมน่าเพิ่มขึ้น [Arg3] % และเริ่มต้นการต่อสู้จะได้รับพลังงานกุญแจเงินจำนวน [Arg4] % ของการฟื้นฟูพลังงานกุญแจเงินของราโมน่า。"
  },
  AwakerTalent_74133_TalentDesc_6 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้มีค่า CON, การโจมตี, การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน หลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก\n·ฟื้นฟูพลังงานกุญแจเงินของราโมน่าเพิ่มขึ้น [Arg3]％ และได้รับพลังงานกุญแจเงินจำนวน [Arg4]％ เมื่อเริ่มต้นการต่อสู้。"
  },
  AwakerTalent_74133_TalentDesc_7 = {
    Text = "·พรสวรรค์นี้ใช้ได้เฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มี CON,โจมตี,การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน หลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก。\n·การฟื้นฟูพลังงานกุญแจเงินของราโมน่าเพิ่มขึ้น [Arg3]％ และได้รับพลังงานกุญแจเงินจำนวน [Arg4]％ เมื่อเริ่มต้นการต่อสู้。"
  },
  AwakerTalent_74133_TalentDesc_8 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่าร่างกาย，การโจมตี，และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้หลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรกจะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน。\n·การฟื้นฟูพลังงานกุญแจเงินของราโมน่าจะเพิ่มขึ้น [Arg3]％，และในช่วงเริ่มต้นการต่อสู้จะได้รับพลังงานกุญแจเงินจำนวน [Arg4]％。"
  },
  AwakerTalent_74133_TalentDesc_9 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้จะมีค่า CON, การโจมตี, การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก\n·การฟื้นฟูพลังงานกุญแจเงินของราโมน่าจะเพิ่มขึ้น [Arg3] % และจะได้รับพลังงานกุญแจเงิน [Arg4] % ในช่วงเริ่มต้นการต่อสู้。"
  },
