  AwakerTalent_74133_TalentName_9 = {
    Text = "ศักยภาพแห่งวิญญาณ"
  },
  AwakerTalent_74134_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON, การโจมตี และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] หลังจากการตื่นรู้ครั้งแรก\n·เฮลอตทำให้ความเสียหายสุดท้ายที่ทำต่อศัตรูใน「ทุ่งหิมะ」เพิ่มขึ้น [Arg3] % หากในรอบนี้เฮลอตใช้「ตัวอ่อน」เกินไป ความเสียหายจากการโจมตีคริติคอลในรอบนี้จะเพิ่มขึ้น + [Arg4] %。"
  },
  AwakerTalent_74134_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มีค่าร่างกาย โจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากที่ใช้การตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·เฮลอตทำให้ความเสียหายสุดท้ายที่ทำต่อศัตรูใน「ทุ่งหิมะ」เพิ่มขึ้น [Arg3]%。หากในรอบนี้เฮลอตใช้「ตัวอ่อน」มากเกินไป ความเสียหายจากการโจมตีคริติคอลในครั้งถัดไปจะเพิ่มขึ้นอีก [Arg4] %。"
  },
  AwakerTalent_74134_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้จะมีค่า CON, โจมตี, การป้องกันเพิ่มขึ้น [Arg1] % และจะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากที่เล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก\n·เฮลอตทำความเสียหายสุดท้ายให้กับศัตรูใน「ทุ่งหิมะ」เพิ่มขึ้น [Arg3]％ หากในรอบนี้เฮลอตใช้「ตัวอ่อน」ความเสียหายในครั้งถัดไปจะเพิ่มความเสียหายคริติคอล + [Arg4]％"
  },
  AwakerTalent_74134_TalentDesc_3 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่า CON, โจมตี, การป้องกันเพิ่มขึ้น [Arg1] % และเมื่อผู้ปลุกตื่นนี้ใช้การตื่นรู้ครั้งแรกจะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน。\n·เฮลอตทำความเสียหายในด่าน「ทุ่งหิมะ」เพิ่มขึ้น [Arg3] %。หากในรอบนี้เฮลอตใช้「ตัวอ่อน」เกินไป ความเสียหายจากการโจมตีคริติคอลในครั้งถัดไปจะเพิ่มขึ้น + [Arg4] %。"
  },
  AwakerTalent_74134_TalentDesc_4 = {
    Text = "· พรสวรรค์นี้มีผลเฉพาะเมื่ออยู่ในด่าน 「บทแห่งดวงดาว」 \n· ค่าสถานะของร่างปลุกนี้: ความแข็งแกร่ง, พลังโจมตี และการป้องกัน เพิ่มขึ้น [Arg1] % และหลังจากร่างปลุกนี้ครั้งแรกโจมตีพร้อมกับปลุกพลังแห่งจิตจะได้รับพลังประตูเงิน [Arg2] จุด \n· ไฮโรทำความเสียหายสุดท้ายกับศัตรู 「ทุ่งน้ำแข็ง」 เพิ่มขึ้น [Arg3]％ ถ้าในเทิร์นนี้ไฮโรใช้ 「ตัวอ่อน」 ในการโจมตี ความเสียหายคริติคอลในครั้งต่อไปที่ทำการโจมตีในเทิร์นนี้จะ + [Arg4]％"
  },
  AwakerTalent_74134_TalentDesc_5 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะได้รับความสามารถทางกายภาพ การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากที่เล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·เฮลอตทำความเสียหายสุดท้ายให้กับศัตรูใน「ทุ่งหิมะ」เพิ่มขึ้น [Arg3]%。หากในรอบนี้เฮลอตใช้「ตัวอ่อน」แล้ว ครั้งถัดไปที่ทำความเสียหายจะเพิ่มดาเมจคริติคอล + [Arg4] %。"
  },
  AwakerTalent_74134_TalentDesc_6 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้จะมีค่า CON, การโจมตี, และการป้องกันเพิ่มขึ้น [Arg1] % และหลังจากที่ผู้ปลุกตื่นนี้ใช้การตื่นรู้ครั้งแรก จะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน\n·เฮลอตทำให้ความเสียหายสุดท้ายที่ทำกับศัตรูใน「ทุ่งหิมะ」เพิ่มขึ้น [Arg3] % หากในรอบนี้เฮลอตใช้「ตัวอ่อน」เกินไป ความเสียหายคริติคอลในรอบนี้จะเพิ่มขึ้น + [Arg4] % เมื่อทำความเสียหายครั้งถัดไป。"
  },
  AwakerTalent_74134_TalentDesc_7 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่า CON，โจมตี，การป้องกันเพิ่มขึ้น [Arg1] % และจะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากที่ได้เล่นการตื่นรู้ครั้งแรก。\n·เฮลอตจะทำให้ความเสียหายสุดท้ายที่สร้างให้กับศัตรูใน「ทุ่งหิมะ」เพิ่มขึ้น [Arg3] %。หากในรอบนี้เฮลอตได้ใช้「ตัวอ่อน」ความเสียหายคริติคอลในการโจมตีครั้งถัดไปจะเพิ่มขึ้น + [Arg4] %。"
  },
  AwakerTalent_74134_TalentDesc_8 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ความสามารถทางกายภาพ,การโจมตีและการป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก。\n·ดาเมจสุดท้ายที่เฮลอตทำให้กับศัตรูใน「ทุ่งหิมะ」เพิ่มขึ้น [Arg3] %。หากในรอบนี้เฮลอตใช้「ตัวอ่อน」，ดาเมจที่เขาจะทำในรอบนี้จะมีความเสียหายจากการโจมตีคริติคอลเพิ่มขึ้น + [Arg4] %。"
  },
  AwakerTalent_74134_TalentDesc_9 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ร่างกายที่ปลุกตื่นนี้จะมีค่า CON, การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ร่างกายที่ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากใช้การตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·เฮลอตจะสร้างความเสียหายสุดท้ายที่เพิ่มขึ้น [Arg3] % ให้กับศัตรูใน「ทุ่งหิมะ」。如果ในรอบนี้เฮลอตใช้「ตัวอ่อน」，ความเสียหายจากการโจมตีคริติคอลในการสร้างความเสียหายครั้งถัดไปจะเพิ่มขึ้น + [Arg4] %。"
  },
