  AwakerTalent_74135_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON,      โจมตี,      การป้องกัน ขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนน หลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก.\n·เมื่อเริ่มการต่อสู้บอส จะได้รับการต้านทานความตายเท่ากับ [Arg3]% ของคุณสมบัติการต้านทานความตายของออร์ลา.ทุกครั้งที่กระตุ้นการต้านทานความตาย จนกว่าจะสิ้นสุดเทิร์น ผลของ「บทแห่งความงดงาม」ที่เกี่ยวข้องจะเพิ่มขึ้น [Arg4]%."
