  AwakerTalent_74136_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน 「บทแห่งดวงดาว」 เท่านั้น。\n·สภาวะที่ตื่นขึ้นนี้จะเพิ่มพลังชีวิต การโจมตี และการป้องกันขึ้น [Arg1] % และเมื่อใช้ทักษะปลุกชีวิตครั้งแรก จะได้รับพลังงานกุญแจเงิน [Arg2] จุด。\n·เมื่อเริ่มการต่อสู้ จะได้รับการ์ด 「เปลวไฟเขียวแบบคอร์รัปต์」 ซึ่งมีคำอธิบาย 「การใช้จ่าย」 1 ใบในมือ และเพิ่มความเสียหายพื้นฐานของ 「เปลวไฟเขียว」 และการ์ดที่เกี่ยวข้อง [Arg3] %。"
  },
  AwakerTalent_74136_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่า CON, การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และเมื่อผู้ปลุกตื่นนี้เล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก จะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน。\n·เมื่อเริ่มต้นการต่อสู้ จะมีการ์ด「เปลวไฟสีเขียวเน่าเปื่อย」ที่ใช้「ใช้」เพิ่มอีก 1 ใบในมือ และทำให้ความเสียหายพื้นฐานของ「เปลวไฟสีเขียว」และการ์ดต่อยอดที่เกี่ยวข้องเพิ่มขึ้น [Arg3] %。"
  },
  AwakerTalent_74136_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะได้รับค่า CON, โจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน หลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·เมื่อเริ่มต้นการต่อสู้ จะมีการเพิ่มการ์ด「การใช้」ที่ถูกแนบมาเป็น「เปลวไฟสีเขียวเน่าเปื่อย」จำนวน 1 ใบในมือ และจะทำให้ความเสียหายพื้นฐานของ「เปลวไฟสีเขียว」และการ์ดที่เกี่ยวข้องเพิ่มขึ้น [Arg3] %。"
  },
  AwakerTalent_74136_TalentDesc_3 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มีค่า CON, โจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และเมื่อผู้ปลุกตื่นนี้เล่นการตื่นรู้วิญญาณ จะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน。\n·เมื่อเริ่มต้นการต่อสู้ จะมีการ์ด「เปลวไฟสีเขียวเน่าเปื่อย」ที่ใช้แล้วเพิ่มอีก 1 ใบอยู่ในมือ และจะทำให้ความเสียหายพื้นฐานของ「เปลวไฟสีเขียว」และการ์ดที่เกี่ยวข้องเพิ่มขึ้น [Arg3] %。"
  },
  AwakerTalent_74136_TalentDesc_4 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่า CON, การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·เมื่อเริ่มต้นการต่อสู้ จะมีการ์ด「เปลวไฟสีเขียวเน่าเปื่อย」ที่ใช้แล้วเพิ่มอีก 1 ใบอยู่ในมือ และทำให้ความเสียหายพื้นฐานของ「เปลวไฟสีเขียว」และการ์ดต่อยอดที่เกี่ยวข้องเพิ่มขึ้น [Arg3] %。"
  },
  AwakerTalent_74136_TalentDesc_5 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน \"บทดารา\" เท่านั้น。\n·ร่างปลุกพลังนี้ได้รับการเพิ่มค่าร่างกาย, การโจมตี, และการป้องกันขึ้น [Arg1] % และเมื่อปลุกพลังปราณครั้งแรกจะได้รับพลังงาน \"กุญแจเงิน\" [Arg2] จุด。\n·เมื่อเริ่มการต่อสู้ จะได้รับการ์ด \"เปลวไฟเขียวเน่า\" ซึ่งมีคุณสมบัติ \"ผลาญ\" 1 ใบในมือ และเพิ่มค่าพื้นฐานความเสียหายของ \"เปลวไฟเขียว\" และการ์ดที่เกี่ยวข้องขึ้น [Arg3] %。"
  },
  AwakerTalent_74136_TalentDesc_6 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้จะได้รับค่า CON, การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก\n·เมื่อเริ่มต้นการต่อสู้ จะมีการวางการ์ด「เปลวไฟสีเขียวเน่าเปื่อย」ที่ใช้แล้ว 1 ใบในมือ และทำให้ความเสียหายพื้นฐานของ「เปลวไฟสีเขียว」และการ์ดต่อยอดที่เกี่ยวข้องเพิ่มขึ้น [Arg3]％。"
  },
  AwakerTalent_74136_TalentDesc_7 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่มค่าพื้นฐานของ CON, การโจมตี และการป้องกันขึ้น [Arg1] % และเมื่อผู้ปลุกตื่นนี้ใช้การตื่นรู้ครั้งแรกจะได้รับพลังงานกุญแจเงิน [Arg2] คะแนน。\n·เมื่อเริ่มการต่อสู้ จะมีการ์ด「การใช้」ที่เพิ่มขึ้น 1 ใบ「เปลวไฟสีเขียวเน่าเปื่อย」เข้าไปในมือ และจะทำให้ความเสียหายพื้นฐานของ「เปลวไฟสีเขียว」และการ์ดที่เกี่ยวข้องเพิ่มขึ้น [Arg3] %。"
