  AwakerTalent_74136_TalentDesc_8 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่มค่า CON, การโจมตี และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก。\n·เมื่อเริ่มต้นการต่อสู้ จะมีการเพิ่มการ์ด「การใช้」ที่เป็น「เปลวไฟสีเขียวเน่าเปื่อย」จำนวน 1 ใบในมือ และจะทำให้ความเสียหายพื้นฐานของ「เปลวไฟสีเขียว」และการ์ดต่อยอดที่เกี่ยวข้องเพิ่มขึ้น [Arg3] %。"
  },
  AwakerTalent_74136_TalentDesc_9 = {
