    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น\n·CON, โจมตี, การป้องกันของร่างตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ร่างตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก\n·เมื่อ「ซากปรักหักพังแห่งเถ้าถ่าน」รีเฟรช อัตราความน่าจะเป็นที่จะปรากฏส่วนลดเพิ่มขึ้น [Arg3]％ และอัตราส่วนลดเพิ่มขึ้น [Arg4]％\n·ความเสียหายพื้นฐานของ「คอขาดสะบั้น」เพิ่มขึ้น [Arg5] % คำนวณแยกจากความเสียหายพื้นฐานที่เพิ่มขึ้นจากการสังหาร"
  },
