    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะเพิ่มค่าร่างกาย,      การโจมตี,      การป้องกัน [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก.\n·เคเคสทุกเทิร์นเมื่อเล่นการ์ดคำสั่งใบแรกจะฟื้นฟูพลังชีวิต [Arg3]% ของ CON ตนเอง.การโจมตีหนวดและเอฟเฟกต์ตอบโต้ของ「สายเลือดจากนอกรีต」สร้างความเสียหายเพิ่มเติม [Arg4]％."
