  AwakerTalent_74139_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้มีค่า CON,     โจมตี,     การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·การโต้กลับที่โนติร่าสร้างเพิ่มขึ้น [Arg3]％「เตรียมพร้อมรบ」ก่อนปล่อยจะได้รับการโต้กลับชั่วคราวเท่ากับ [Arg4]％ ของการโต้กลับถาวร."
  },
