  AwakerTalent_74140_TalentName_9 = {
    Text = "ศักยภาพแห่งวิญญาณ"
  },
  AwakerTalent_74141_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้ใช้ได้เฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON, การโจมตี, การป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·หลังจากเริ่มต้นการสำรวจ จะทำให้ความเสียหายจากพิษ, การโต้กลับ, ความเสียหายพื้นฐานที่ผู้ปลุกตื่นทั้งหมดทำเพิ่มขึ้น [Arg3] %。"
  },
  AwakerTalent_74141_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่มค่าร่างกาย, การโจมตี, และการป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนเมื่อเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·หลังจากเริ่มต้นการสำรวจ จะทำให้ความเสียหายจากพิษ, การโต้กลับ และความเสียหายพื้นฐานที่ทำโดยผู้ปลุกตื่นทั้งหมดเพิ่มขึ้น [Arg3]％。"
  },
  AwakerTalent_74141_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ค่าความทนทาน, การโจมตี, และการป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก。\n·หลังจากเริ่มต้นการสำรวจ ความเสียหายที่เกิดจากพิษ, การโต้กลับ, และความเสียหายพื้นฐานของผู้ปลุกตื่นทั้งหมดจะเพิ่มขึ้น [Arg3]％。"
  },
  AwakerTalent_74141_TalentDesc_3 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON, การโจมตี, การป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนเมื่อเล่นวิญญาณตื่นรู้เป็นครั้งแรก。\n·หลังจากเริ่มต้นการสำรวจแล้ว จะทำให้ความเสียหายจากพิษ, การโต้กลับ, ความเสียหายพื้นฐานที่ทุกผู้ปลุกตื่นทำเพิ่มขึ้น [Arg3]％。"
  },
