  AwakerTalent_74141_TalentDesc_9 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้ความสามารถ, การโจมตี, การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากที่เล่นวิญญาณตื่นรู้เป็นครั้งแรก。\n·หลังจากการเริ่มต้นการสำรวจ ความเสียหายที่เกิดจากพิษ, การโต้กลับ, ความเสียหายพื้นฐานของผู้ปลุกตื่นทั้งหมดเพิ่มขึ้น [Arg3]％。"
