  AwakerTalent_74201_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะได้รับการเพิ่มขึ้นของ CON, โจมตี, และการป้องกันจำนวน [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก。\n·การฟื้นฟูพลังงานกุญแจเงินของราโมน่าจะเพิ่มขึ้น [Arg3] % เมื่อเริ่มต้นการต่อสู้จะได้รับพลังงานกุญแจเงินจำนวน [Arg4] % จากการฟื้นฟูพลังงานกุญแจเงินของราโมน่า。"
  },
  AwakerTalent_74201_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON, การโจมตี, การป้องกัน [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก\n·การชาร์จกุญแจเงินของราโมน่า: วัฏกาลเพิ่มขึ้น [Arg3] % และจะได้รับพลังงานกุญแจเงิน [Arg4] % ของการชาร์จกุญแจเงินราโมน่า: วัฏกาลเมื่อเริ่มต้นการต่อสู้。"
  },
  AwakerTalent_74201_TalentDesc_2 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้มีค่าร่างกาย การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก。\n·การชาร์จกุญแจเงินของราโมน่าเพิ่มขึ้น [Arg3] % และได้รับพลังงานกุญแจเงินจำนวน [Arg4] % ของการชาร์จกุญแจเงินของราโมน่าเมื่อเริ่มต้นการต่อสู้。"
  },
