  AwakerTalent_78618_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้ใช้ได้เฉพาะในด่าน「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้มีค่า CON,      การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก.\n·เอฟเฟกต์ความเสียหายพื้นฐานที่「การไถ่บาปแห่งความทุกข์」สร้างจะเพิ่มขึ้นเท่ากับ [Arg3]％ ของพลังโจมตีของโพลลักซ์.\n·ทุกครั้งที่สะสม「ตราบาป」ครบ 50 ชั้น จะนำ「หัวใจศักดิ์สิทธิ์」1 ใบเข้ามือ.\n·หลังจาก「ตราบาป」ถึง 100 ชั้น เมื่อ「หัวใจศักดิ์สิทธิ์」ถูกใช้จากการเล่นครั้งที่ 3 จะจั่ว「การ์ดสกิล」ของตัวเอง 1 ใบ.\n·เมื่อสร้างความเสียหาย เอฟเฟกต์ของ「ตราบาป」ต่อศัตรู「คริสตจักรโคมไฟ」จะเพิ่มเป็นสองเท่า."
  },
  AwakerTalent_78618_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้ใช้ได้เฉพาะในด่าน「บทของดวงดาว」\n·ผู้ปลุกตื่นนี้มีค่า CON,      การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้เป็นครั้งแรก.\n·เอฟเฟกต์ความเสียหายพื้นฐานที่「การไถ่บาปแห่งความทุกข์」สร้างจะเพิ่มขึ้นเท่ากับ [Arg3]％ ของพลังโจมตีของโพลลักซ์.\n·ทุกครั้งที่สะสม「ตราบาป」ครบ 50 ชั้น จะนำ「หัวใจศักดิ์สิทธิ์」1 ใบเข้ามือ.\n·หลังจาก「ตราบาป」ถึง 100 ชั้น เมื่อ「หัวใจศักดิ์สิทธิ์」ถูกใช้จากการเล่นครั้งที่ 3 จะจั่ว「การ์ดสกิล」ของตัวเอง 1 ใบ.\n·เมื่อสร้างความเสียหาย เอฟเฟกต์ของ「ตราบาป」ต่อศัตรู「คริสตจักรโคมไฟ」จะเพิ่มเป็นสองเท่า."
