  AwakerTalent_78620_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「星辰篇」เท่านั้น.\n·CON, การโจมตี, การป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] ％ และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] จุด หลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·เมื่อเริ่มการต่อสู้, ทำให้ศัตรูทั้งหมดรับความเสียหายจากหนวดที่ได้รับเพิ่มขึ้น [Arg3]％, ผลเป็นสองเท่าสำหรับศัตรู「เอควอ」. ดาเมจสกิลกดใช้ของ「อสนีบาตลงทัณฑ์」ที่สร้างให้ศัตรู「เอควอ」เพิ่มขึ้น [Arg4]％."
  },
