    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะมีค่า CON,      การโจมตี,      การป้องกันเพิ่มขึ้น [Arg1] % และเมื่อผู้ปลุกตื่นนี้เล่นการตื่นรู้ทางจิตวิญญาณครั้งแรกจะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน.\n·ผลเพิ่มพลังของ「เปลวเพลิงมีชีวิต」เพิ่มขึ้น [Arg3]％ หลังเริ่มเทิร์นและก่อนเฟสทิ้งการ์ด ลบ「การเผาไหม้」ของการ์ดในมือทั้งหมด แต่ละชั้นทำให้เคทิกูลาได้รับ 1 ชั้น「เปลวระเบิด」."
  },
