  AwakerTalent_78623_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「星辰篇」เท่านั้น.\n·CON, การโจมตี, การป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] ％ และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] จุด หลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·อัตราคริติคอลและดาเมจคริติคอลของระเบิดพลังอาลีมัสของคาราบูเพิ่มขึ้น [Arg3]％. HP สูงสุดที่「อิ่มหนำ」ให้เพิ่มขึ้น [Arg5]％. ในภูมิประเทศ「ทุ่งน้ำแข็ง」,「คำสาปปุยหิมะ」แต้มอริธเมทิกา–1, จำนวนครั้งที่สร้างความเสียหาย +1 และผลความเสียหายและอ่อนแอมีผลต่อศัตรูทั้งหมด."
  },
  AwakerTalent_78623_TalentDesc_10 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「星辰篇」เท่านั้น.\n·CON, การโจมตี, การป้องกันของผู้ปลุกตื่นนี้เพิ่มขึ้น [Arg1] ％ และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] จุด หลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·อัตราคริติคอลและดาเมจคริติคอลของระเบิดพลังอาลีมัสของคาราบูเพิ่มขึ้น [Arg3]％. HP สูงสุดที่「อิ่มหนำ」ให้เพิ่มขึ้น [Arg5]％. ในภูมิประเทศ「ทุ่งน้ำแข็ง」,「คำสาปปุยหิมะ」แต้มอริธเมทิกา–1, จำนวนครั้งที่สร้างความเสียหาย +1 และผลความเสียหายและอ่อนแอมีผลต่อศัตรูทั้งหมด."
  },
