  AwakerTalent_78624_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」.\n·ร่างกายที่ตื่นนี้จะเพิ่ม CON,      ATK,      การป้องกันขึ้น [Arg1] % และทำให้ร่างกายที่ตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก.\n·การเล่น「ขนนกสีนิล」จะไม่เพิ่ม「การประสานอริธเมทิกา」,     การกัดกร่อนที่「ลูกขนศักดิ์สิทธิ์ชำระบาป」ใส่จะเพิ่มพลังการโจมตีของคัสเตอร์ [Arg3]％.\n·การกัดกร่อนที่คัสเตอร์ใส่ให้ศัตรู「คริสตจักรตะเกียง」เพิ่มขึ้น [Arg4]％."
  },
