  AwakerTalent_78625_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะมีค่า CON,      การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณเป็นครั้งแรก.\n·「ความจริง ก็คือภาพลวง」เพิ่มเติมทำให้ความเสียหายสุดท้ายจากการปะทุพลังบ้าคลั่งของผู้ปลุกตื่นอื่นในเทิร์นนี้เพิ่มขึ้น [Arg3]％ หลังใช้แล้วพลังบ้าคลั่งพื้นฐานของพิคแมนจะลดลง 5 คะแนน."
