  AwakerTalent_78636_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่า CON, การโจมตี และการป้องกันเพิ่มขึ้น [Arg1] % และเมื่อผู้ปลุกตื่นนี้เล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก จะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน。"
  },
  AwakerTalent_78636_TalentDesc_10 = {
