  AwakerTalent_78642_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้มีค่า CON,      การโจมตี,      การป้องกันเพิ่มขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากเล่นวิญญาณตื่นรู้ครั้งแรก.\n·「การตัดสินชะตากรรม」ที่อาราคเน่สร้างเพิ่มขึ้น [Arg3]％ 「การตัดสินชะตากรรม」ที่สร้างต่อศัตรูกลายพันธุ์จะเพิ่มเป็นสองเท่า."
  },
