    Text = "·พรสวรรค์นี้มีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้มีค่า CON,      การโจมตี,      การป้องกันเพิ่มขึ้น [Arg1]%,     และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนนหลังจากปลุกตื่นครั้งแรก.\n·พละกำลังที่ได้รับจากผู้ปลุกตื่นทั้งหมดเพิ่มขึ้น [Arg3]％.\n·คลีเมนไทน์เมื่อทำดาเมจให้กับศัตรู「อินเซคทอยด์」จะใส่ผลเลือดออก [Arg4]％ ดาเมจให้กับเป้าหมาย.ในแต่ละรอบที่คลีเมนไทน์ทำโล่หรือฟื้นฟูเลือดครั้งแรก จะทำให้ศัตรู「อินเซคทอยด์」สูญเสียพละกำลังการป้องกันชั่วคราว [Arg5]％."
  },
