  AwakerTalent_78646_TalentDesc_1 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในระดับ「บทของดวงดาว」เท่านั้น。\n·ผู้ปลุกตื่นนี้จะมีค่าความทนทาน,โจมตี,การป้องกันเพิ่มขึ้น [Arg1] % และเมื่อผู้ปลุกตื่นนี้เล่นการตื่นรู้ทางจิตวิญญาณครั้งแรกจะได้รับพลังงานกุญแจเงินจำนวน [Arg2] คะแนน。"
  },
  AwakerTalent_78646_TalentDesc_10 = {
