  AwakerTalent_78911_TalentDesc_6 = {
    Text = "·พรสวรรค์นี้จะมีผลเฉพาะในด่าน「บทของดวงดาว」เท่านั้น.\n·ผู้ปลุกตื่นนี้จะเพิ่ม CON,     โจมตี,     การป้องกันขึ้น [Arg1] % และทำให้ผู้ปลุกตื่นนี้ได้รับพลังงานกุญแจเงิน [Arg2] คะแนนหลังจากเล่นการตื่นรู้ทางจิตวิญญาณครั้งแรก.\n·ความเสียหายที่เกิดจากเดลิเรียม·เมอร์ฟีจะเพิ่ม [Arg3]％「บูชายัญ」 เอฟเฟกต์เพิ่มของ「สัญญาชีวิต」ต่อ「พิธีกรรมกำเนิด」จะเพิ่มเป็นสองเท่า.\n·เมื่อในทีมมีผู้ปลุกตื่น「ลิโมเรีย」อื่นอีก 1/2/3 คน จะเพิ่มขีดจำกัด HP ขึ้น 6%/15%/30％.ผู้ปลุกตื่น「ลิโมเรีย」จะได้รับเกราะป้องกันเท่ากับ 50%/125%/250% ของค่าป้องกันของเดลิเรียม·เมอร์ฟีหลังจากปล่อยพลังคลั่ง เอฟเฟกต์นี้มีผลได้สูงสุด 1 ครั้งต่อเทิร์นและไม่ได้รับผลจากเอฟเฟกต์เพิ่มเกราะ."
  },
