  AwakerTalent_79211_TalentDesc_1 = {
    Text = "·การ์ดคำสั่งของคลีเมนไทน์จะได้รับ 1 ชั้น「ความรู้สึกเห็นใจ」หลังจากทำดาเมจ\n·ร่างกายที่ตื่นขึ้นของคลีเมนไทน์, วงล้อมชีวิต, และพันธสัญญาจะเพิ่มพลังงานกุญแจเงิน 1 คะแนน ทำให้อัตราคริติคอลและดาเมจคริติคอลเพิ่มขึ้น 0.35%\n·หลังเริ่มเทิร์นอัลตร้า จะลบ「ความเสียหายทางจิตใจ」และ「การยึดติดด้วยความกลัว」ของศัตรูทั้งหมด ในการลบ「ความเสียหายทางจิตใจ」 1 ชั้นของศัตรูทั้งหมดจะได้รับพลังงานกุญแจเงิน 50 คะแนน และในการลบ「การยึดติดด้วยความกลัว」 1 ชั้นของศัตรูทั้งหมดจะทำให้ร่างกายที่ตื่นขึ้นอื่นๆ ได้รับอาลีมัส 2 คะแนน。"
  },
