  AwakerTalent_83778_TalentDesc_1 = {
    Text = "·ครอปเปอร์ซันท์ตัวเองและอุปกรณ์ ทุก 1% ของการต่อต้านการตายเพิ่มความเสียหายพื้นฐาน 0.2% และเพิ่มโล่ 0.05%。"
  },
  AwakerTalent_83778_TalentName_1 = {
    Text = "เถ้าถ่าน"
  },
  AwakerTalent_84132_TalentDesc_1 = {
    Text = "·ออริตาทุก 1 ระดับการชาร์จความคลั่ง จะได้รับความเสียหายจากหนวดสัมผัส 2% ของ ATK ของออริตาเมื่อการต่อสู้เริ่มต้นขึ้น,      ทุก 1% อัตราคริติคอล จะได้รับความเสียหายจากหนวดสัมผัส 1% ของ ATK ของออริตาเมื่อการต่อสู้เริ่มต้นขึ้น."
  },
  AwakerTalent_84132_TalentName_1 = {
    Text = "ภูติจิ๋วสุขสันต์"
  },
  AwakerTalent_89775_TalentDesc_1 = {
    Text = "·เมื่อเล่น「ขนนกสีนิล」ครั้งแรกในแต่ละรอบ จะใช้「กัดกร่อน」ที่มีพลังโจมตีของตนเอง 840％ กับศัตรูทั้งหมดและได้รับ 10 อาลีมัส.\n·ทุก ๆ 1% ของความเสียหายเพิ่มขึ้นของคาสเตอร์ จะทำให้「กัดกร่อน」พื้นฐานที่ใช้เพิ่มขึ้น 1%.\n·หลังจากการต่อสู้สิ้นสุดลง ความเสียหาย「กัดกร่อน」ที่คาสเตอร์ใช้ในสำรวจนี้จะเพิ่มขึ้น 20％ ตลอดไป.\n·「กัดกร่อน」ที่ใช้ในการต่อสู้กับผู้นำจะเพิ่มขึ้นเป็นสองเท่า.\n·หลังจากที่คาสเตอร์ใช้「กัดกร่อน」ความเสียหายของตนเองในรอบนี้จะเพิ่มขึ้น 5% ของปริมาณที่ใช้.\n·ความเสียหายที่คาสเตอร์ทำจะไม่ลบ「กัดกร่อน」."
  },
  AwakerTalent_89775_TalentName_1 = {
    Text = "ลูกขนศักดิ์สิทธิ์ชำระบาป"
  },
  AwakerTalent_95804_TalentDesc_1 = {
    Text = "·ดูเรซินสังหารศัตรูหรือใช้ระเบิดพลังทำดาเมจให้ผู้นำจะได้รับ 1 ชิ้น「ซากปรักหักพัง」.\n·สะสมได้สูงสุด 3 ชิ้น.\n·「ซากปรักหักพัง」จะถูกถ่ายทอดไปยังการต่อสู้ครั้งถัดไป."
