  AwakerTalent_98451_TalentDesc_1 = {
    Text = "·เมื่อเริ่มรอบ จะมอบ「เปลวไฟที่มีชีวิต」 1 ชั้นให้กับการ์ดคำสั่ง คาเทกูล่า 1 ใบในมือแบบสุ่ม.\n·คาเทกูล่าจะได้รับ「เปลวไฟที่มีชีวิต」เพิ่ม 1 ชั้นเมื่อใช้「เปลวไฟ」 1 ชั้น.\n·เมื่อ「เปลวไฟ」สะสมถึง 10 ชั้น จะได้รับ 2 จุดอริธเมติกา และอัปเกรด「แสงสว่างระลอกพันล้าน」เป็น「แสงสว่างระลอกหมื่นล้าน」."
